import { useRef, useEffect } from 'react';

const useTooltipManager = () => {
  // Ref to track active tooltip ID
  const activeTooltipRef = useRef(null);

  // Handle tooltip repositioning on window resize or scroll
  useEffect(() => {
    const handleWindowChange = () => {
      const tooltipId = activeTooltipRef.current;
      if (tooltipId) {
        const tooltip = document.getElementById(tooltipId);
        if (tooltip) {
          // Remove the tooltip if window size changes or scrolling occurs
          document.body.removeChild(tooltip);
          activeTooltipRef.current = null;
        }
      }
    };

    window.addEventListener('resize', handleWindowChange);
    window.addEventListener('scroll', handleWindowChange);

    return () => {
      window.removeEventListener('resize', handleWindowChange);
      window.removeEventListener('scroll', handleWindowChange);
    };
  }, []);

  // Clean up any tooltips when component unmounts
  useEffect(() => {
    return () => {
      const tooltipId = activeTooltipRef.current;
      if (tooltipId) {
        const tooltip = document.getElementById(tooltipId);
        if (tooltip) {
          document.body.removeChild(tooltip);
        }
      }
    };
  }, []);

  const showTooltip = (id, x, y) => {
    // Remove any existing tooltip
    const oldTooltipId = activeTooltipRef.current;
    if (oldTooltipId) {
      const oldTooltip = document.getElementById(oldTooltipId);
      if (oldTooltip) {
        document.body.removeChild(oldTooltip);
      }
    }

    // Update the active tooltip ref
    activeTooltipRef.current = id;

    // Position the tooltip
    const tooltip = document.getElementById(id);
    if (tooltip) {
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }
  };

  const hideTooltip = () => {
    const tooltipId = activeTooltipRef.current;
    if (tooltipId) {
      const tooltip = document.getElementById(tooltipId);
      if (tooltip) {
        document.body.removeChild(tooltip);
      }
      activeTooltipRef.current = null;
    }
  };

  return {
    activeTooltipRef,
    showTooltip,
    hideTooltip
  };
};

export default useTooltipManager;
